UPDATE inv_stock
SET qty     = qty + #{delta},
    version = version + 1
WHERE warehouse_id = #{warehouseId}
  AND material_id = #{materialId}
  AND batch_no = #{batchNo}
  AND location_id = #{locationId}
  AND deleted = 0

UPDATE inv_stock
SET qty     = qty + #{delta},
    version = version + 1
WHERE warehouse_id = #{warehouseId}
  AND material_id = #{materialId}
  AND batch_no = #{batchNo}
  AND location_id = #{locationId}
  AND deleted = 0
  AND qty + #{delta} >= 0

UPDATE inv_stock
SET expiry_date = #{expiryDate},
    version     = version + 1
WHERE warehouse_id = #{warehouseId}
  AND material_id = #{materialId}
  AND batch_no = #{batchNo}
  AND location_id = #{locationId}
  AND deleted = 0
  AND expiry_date IS NULL

mapper.select:
SELECT id, warehouse_id, material_id, batch_no, location_id, first_in_at, expiry_date, qty, version
FROM inv_stock
WHERE warehouse_id = #{warehouseId}
  AND material_id = #{materialId}
  AND batch_no = #{batchNo}
  AND location_id = #{locationId}
  AND deleted = 0

SELECT MIN(s.id) AS id, s.warehouse_id, w.code AS warehouse_code, w.name AS warehouse_name, s.material_id, m.code AS material_code, m.name AS material_name, s.batch_no, SUM(s.qty) AS qty, MIN(s.first_in_at) AS first_in_at, MIN(s.expiry_date) AS expiry_date, DATEDIFF(CURRENT_DATE, DATE(MIN(s.first_in_at))) AS age_days FROM inv_stock s LEFT JOIN base_warehouse w ON w.id = s.warehouse_id LEFT JOIN base_material m ON m.id = s.material_id WHERE s.deleted = 0 AND s.batch_no != '' AND s.material_id = #{materialId}
AND s.warehouse_id = #{warehouseId}
GROUP BY s.warehouse_id, w.code, w.name, s.material_id, m.code, m.name, s.batch_no ORDER BY MIN(s.expiry_date) IS NULL, MIN(s.expiry_date) ASC, MIN(s.first_in_at) ASC, s.batch_no
